import sys
import json
import os
import ast
from pathlib import Path

workspace = sys.argv[1]
checks = []

def make_check(name, passed, detail):
    return {"name": name, "passed": passed, "detail": detail}

# -----------------------------------------------------------------------
# CHECK 1: Workflow file exists and was created via the CLI
# The CLI stamps files with "# Generated by evoagentx_cli.py create-workflow"
# The file should be named data_quality_workflow.py (snake_case of DataQualityWorkflow)
# -----------------------------------------------------------------------
CLI_STAMP = "# Generated by evoagentx_cli.py create-workflow"

workflow_file = None
candidates = list(Path(workspace).rglob("data_quality_workflow.py"))

try:
    if not candidates:
        checks.append(make_check(
            "workflow_file_exists",
            False,
            "data_quality_workflow.py not found anywhere in workspace"
        ))
    else:
        workflow_file = candidates[0]
        checks.append(make_check(
            "workflow_file_exists",
            True,
            f"Found at {workflow_file}"
        ))
except Exception as e:
    checks.append(make_check("workflow_file_exists", False, f"Exception: {e}"))

# -----------------------------------------------------------------------
# CHECK 2: File contains CLI stamp (was generated via create-workflow command)
# -----------------------------------------------------------------------
workflow_content = ""
try:
    if workflow_file and workflow_file.exists():
        workflow_content = workflow_file.read_text()
        has_stamp = CLI_STAMP in workflow_content
        checks.append(make_check(
            "cli_stamp_present",
            has_stamp,
            "CLI stamp found in file" if has_stamp else
            f"Missing CLI stamp '{CLI_STAMP}'. File may not have been created via the CLI."
        ))
    else:
        checks.append(make_check("cli_stamp_present", False, "Workflow file not available"))
except Exception as e:
    checks.append(make_check("cli_stamp_present", False, f"Exception: {e}"))

# -----------------------------------------------------------------------
# CHECK 3: Correct imports from evoagentx (not generic Python)
# Must import from evoagentx package specifically
# -----------------------------------------------------------------------
try:
    has_evoagentx_import = (
        "from evoagentx import" in workflow_content or
        "import evoagentx" in workflow_content
    )
    checks.append(make_check(
        "evoagentx_import",
        has_evoagentx_import,
        "evoagentx import found" if has_evoagentx_import else
        "No evoagentx import found. Workflow must import from evoagentx package."
    ))
except Exception as e:
    checks.append(make_check("evoagentx_import", False, f"Exception: {e}"))

# -----------------------------------------------------------------------
# CHECK 4: Class inherits from Workflow and is named DataQualityWorkflow
# -----------------------------------------------------------------------
try:
    class_ok = False
    detail = "Could not parse or find class"
    if workflow_content:
        try:
            tree = ast.parse(workflow_content)
            for node in ast.walk(tree):
                if isinstance(node, ast.ClassDef) and node.name == "DataQualityWorkflow":
                    bases = [ast.unparse(b) if hasattr(ast, 'unparse') else getattr(b, 'id', getattr(b, 'attr', '')) for b in node.bases]
                    if any("Workflow" in b for b in bases):
                        class_ok = True
                        detail = f"DataQualityWorkflow(Workflow) found with bases: {bases}"
                        break
                    else:
                        detail = f"DataQualityWorkflow found but doesn't inherit Workflow. Bases: {bases}"
        except SyntaxError as se:
            detail = f"Syntax error in workflow file: {se}"
    checks.append(make_check("class_definition", class_ok, detail))
except Exception as e:
    checks.append(make_check("class_definition", False, f"Exception: {e}"))

# -----------------------------------------------------------------------
# CHECK 5: async def execute(self, context) method present
# -----------------------------------------------------------------------
try:
    has_execute = False
    detail = "execute method not found or not async"
    if workflow_content:
        try:
            tree = ast.parse(workflow_content)
            for node in ast.walk(tree):
                if (isinstance(node, ast.AsyncFunctionDef) and
                        node.name == "execute"):
                    args = [a.arg for a in node.args.args]
                    if "self" in args and "context" in args:
                        has_execute = True
                        detail = "async def execute(self, context) found"
                        break
                    else:
                        detail = f"execute is async but args are: {args}"
        except SyntaxError as se:
            detail = f"Syntax error: {se}"
    checks.append(make_check("async_execute_method", has_execute, detail))
except Exception as e:
    checks.append(make_check("async_execute_method", False, f"Exception: {e}"))

# -----------------------------------------------------------------------
# CHECK 6: References a specific EvoAgentX evolution strategy
# Must mention one of: TextGrad, AFlow, MIPRO
# -----------------------------------------------------------------------
try:
    strategies = ["TextGrad", "AFlow", "MIPRO"]
    found_strategies = [s for s in strategies if s in workflow_content]
    strategy_ok = len(found_strategies) > 0
    checks.append(make_check(
        "evolution_strategy_referenced",
        strategy_ok,
        f"Found strategies: {found_strategies}" if strategy_ok else
        f"None of the required strategies ({strategies}) found in workflow. Must reference at least one."
    ))
except Exception as e:
    checks.append(make_check("evolution_strategy_referenced", False, f"Exception: {e}"))

# -----------------------------------------------------------------------
# CHECK 7: EvolutionEngine usage
# Must import/use EvolutionEngine from evoagentx.evolution
# -----------------------------------------------------------------------
try:
    has_engine = (
        "EvolutionEngine" in workflow_content or
        "evolution" in workflow_content.lower()
    )
    has_evolve_call = "evolve" in workflow_content
    engine_ok = has_engine and has_evolve_call
    checks.append(make_check(
        "evolution_engine_usage",
        engine_ok,
        "EvolutionEngine and evolve() call found" if engine_ok else
        f"EvolutionEngine present: {has_engine}, evolve() call: {has_evolve_call}. Both required."
    ))
except Exception as e:
    checks.append(make_check("evolution_engine_usage", False, f"Exception: {e}"))

# -----------------------------------------------------------------------
# CHECK 8: All four GEP genome fields present in the workflow file
# Required: task_type_classification, approach_methodology, outcome_metrics, context_requirements
# -----------------------------------------------------------------------
GENOME_FIELDS = [
    "task_type_classification",
    "approach_methodology",
    "outcome_metrics",
    "context_requirements",
]
try:
    # Search in workflow file AND any genome config file
    genome_search_content = workflow_content

    # Also search in any genome config file the agent may have created
    genome_files = (
        list(Path(workspace).rglob("genome*.json")) +
        list(Path(workspace).rglob("genome*.yaml")) +
        list(Path(workspace).rglob("genome*.py")) +
        list(Path(workspace).rglob("*genome*.json")) +
        list(Path(workspace).rglob("*genome*.yaml"))
    )
    for gf in genome_files:
        try:
            genome_search_content += "\n" + gf.read_text()
        except Exception:
            pass

    missing = [f for f in GENOME_FIELDS if f not in genome_search_content]
    all_genome_ok = len(missing) == 0
    checks.append(make_check(
        "gep_genome_fields_present",
        all_genome_ok,
        f"All GEP genome fields present" if all_genome_ok else
        f"Missing genome fields: {missing}. All four required: {GENOME_FIELDS}"
    ))
except Exception as e:
    checks.append(make_check("gep_genome_fields_present", False, f"Exception: {e}"))

# -----------------------------------------------------------------------
# CHECK 9: evaluation_criteria with accuracy >= 0.90 specified
# The workflow must configure evaluation_criteria as shown in SKILL.md
# -----------------------------------------------------------------------
try:
    import re
    # Look for evaluation_criteria dict or similar structure
    has_eval_criteria = "evaluation_criteria" in workflow_content
    # Also check for accuracy threshold value
    accuracy_pattern = re.search(r'accuracy.*?0\.\d+', workflow_content)
    criteria_ok = has_eval_criteria and accuracy_pattern is not None
    checks.append(make_check(
        "evaluation_criteria_configured",
        criteria_ok,
        f"evaluation_criteria with accuracy threshold found" if criteria_ok else
        f"evaluation_criteria present: {has_eval_criteria}, accuracy value: {accuracy_pattern}. "
        "Must configure evaluation_criteria with an accuracy threshold."
    ))
except Exception as e:
    checks.append(make_check("evaluation_criteria_configured", False, f"Exception: {e}"))

# -----------------------------------------------------------------------
# CHECK 10: workflow name in description reflects genomics/data quality domain
# The description passed to --description should not be the default
# -----------------------------------------------------------------------
try:
    desc_ok = (
        "Workflow: DataQualityWorkflow" not in workflow_content and
        "description" in workflow_content.lower()
    )
    # Check that a non-trivial description was provided
    # The CLI embeds: "# Description: <value>"
    import re
    desc_match = re.search(r'#\s*Description:\s*(.+)', workflow_content)
    if desc_match:
        desc_value = desc_match.group(1).strip()
        desc_ok = len(desc_value) > 5 and desc_value != "DataQualityWorkflow"
        detail = f"Description found: '{desc_value}'"
    else:
        desc_ok = False
        detail = "No '# Description:' comment found — was create-workflow --description used?"
    checks.append(make_check("workflow_description_set", desc_ok, detail))
except Exception as e:
    checks.append(make_check("workflow_description_set", False, f"Exception: {e}"))

# -----------------------------------------------------------------------
# Final scoring
# -----------------------------------------------------------------------
total = len(checks)
passed_count = sum(1 for c in checks if c["passed"])
score = round(passed_count / total, 3)
all_passed = passed_count == total

result = {
    "passed": all_passed,
    "score": score,
    "checks": checks,
}

print(json.dumps(result, indent=2))